package turbo.toa;
import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.awt.*;import javax.swing.*;import net.runelite.api.*;import net.runelite.api.coords.*;import net.runelite.api.events.GameTick;import net.runelite.client.callback.ClientThread;import net.runelite.client.eventbus.EventBus;
/** Synthetic module lifecycle and state capture; no game startup or inputs. */
public final class ToaModuleTests {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Map<String,Object> playerFields=new HashMap<>();playerFields.put("getWorldLocation",new WorldPoint(3210,3210,0));playerFields.put("getLocalLocation",new LocalPoint(1280,1280));Player player=fake(Player.class,playerFields);Map<String,Object> fields=new HashMap<>();fields.put("getGameState",GameState.LOGIN_SCREEN);fields.put("getLocalPlayer",player);fields.put("getBaseX",3200);fields.put("getBaseY",3200);fields.put("getNpcs",Collections.emptyList());fields.put("getTickCount",10);Client client=fake(Client.class,fields);Constructor<ClientThread> ctor=ClientThread.class.getDeclaredConstructor(Client.class);ctor.setAccessible(true);Path root=Files.createTempDirectory("turbo-toa-module-");ToaModule[] module={null};SwingUtilities.invokeAndWait(()->{module[0]=new ToaModule(client,construct(ctor,client),new EventBus(),null,root,()->{});module[0].window().setLocation(-10000,-10000);});ToaModule m=module[0];try{boolean blocked=false;try{m.start();}catch(IllegalStateException e){blocked=true;}check(blocked,"logout must block observation");fields.put("getGameState",GameState.LOGGED_IN);m.start();m.onGameTick(new GameTick());m.onGameTick(new GameTick());check(m.summary().contains("ticks: 1"),"duplicate game ticks must not duplicate frames");m.mark("Purple orb: explain required protection during walkthrough");m.stop("Test stop");fields.put("getTickCount",11);m.onGameTick(new GameTick());check(m.summary().contains("ticks: 1")&&m.summary().contains("mechanic notes: 1"),"stop retains bounded observations without recording more");check(!Files.exists(root.resolve("walkthroughs")),"observations must not auto-save");check(find((Container)m.window(),"Run bot — ToA logic pending").isEnabled()==false,"unimplemented combat must remain unavailable");m.discard();check(m.summary().contains("ticks: 0"),"discard clears observations");System.out.println("ToA module checks passed: independent UI, logout guard, duplicate tick handling, stop, notes, no automatic saves and disabled combat. No game input.");}finally{m.close();Files.delete(root);}System.exit(0);}
 static ClientThread construct(Constructor<ClientThread> ctor,Client client){try{return ctor.newInstance(client);}catch(Exception e){throw new RuntimeException(e);}}
 static JButton find(Container root,String text){for(Component c:root.getComponents()){if(c instanceof JButton&&text.equals(((JButton)c).getText()))return (JButton)c;if(c instanceof Container){JButton found=find((Container)c,text);if(found!=null)return found;}}return null;}
 @SuppressWarnings("unchecked")static <T>T fake(Class<T> type,Map<String,Object> values){return (T)Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(o,m,a)->{if(m.getName().equals("equals"))return o==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(o);if(values.containsKey(m.getName()))return values.get(m.getName());Class<?> t=m.getReturnType();if(t==boolean.class)return false;if(t==int.class)return 0;if(t==long.class)return 0L;return null;});}
}
